    scwin.gAcptNo = $c.frame.path("../").scwin.gAcptNo;
    scwin.gIsurCd = $c.frame.path("../").scwin.gIsurCd;
    // alert("자식창:"+gAcptNo+","+ gIsurCd);

    if (scwin.gLdMktTp === '2') {
        panel_2.hide();
    } else {
        panel_2.hide(); // 유가도 HIDDEN : 2008.07.07 허기영 요청사항

    }
    if (scwin.gLdMktTp === '1') {
        edt_comite_hld_dd.setReadOnly(false);
        edt_comite_hld_dd.style.backgroundColor = '#ffffff';
        edt_comite_hld_dd.ReadOnlyBackgroundColor = '#ffffff';
        img_comite_hld_dd.src = "../img/icn_calendar.gif";
        img_comite_hld_dd.setDisabled(false);
    } else {
        // 코스닥에서는 위원회개최일자는 공시위원회보고서 작성시 입력.
        edt_comite_hld_dd.setReadOnly(true);
        edt_comite_hld_dd.style.backgroundColor = '#b9d4f7';
        edt_comite_hld_dd.ReadOnlyBackgroundColor = '#b9d4f7';
        img_comite_hld_dd.src = "../img/icn_calendar_d.gif";
        img_comite_hld_dd.setDisabled(true);
    }
} < !정보--;
