///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_1);
        fn_GetParentValue();

        // 가우스헤더 셋팅
        const sbmOptions = {
            id : "sbm_dts_nfaith_info",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_nfaith_info=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        // 가우스헤더 셋팅
        const sbmOptions2 = {
            id : "sbm_dts_nfaith",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_nfaith=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        //  정보 읽어오기
        fn_ReadInfo();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35101.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name tr_nfaith_info_OnSuccess
 * @description tr nfaith info On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tr_nfaith_info_OnSuccess = async function() {
    try {
        await $c.win.alert("성공적으로 저장 되었습니다.");
        await $c.win.closePopup();

        // 부모창 reload 처리해야함
        $c.frame.path("../").fn_Search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35101.tr_nfaith_info_OnSuccess" });
    }
};

/**
 * @method
 * @name tr_nfaith_info_OnFail
 * @description tr nfaith info On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tr_nfaith_info_OnFail = async function() {
    try {
        await $c.win.alert('tr_nfaith_info.OnFail() :' + tr_nfaith_info.ErrorMsg);
        dts_nfaith.Reset();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35101.tr_nfaith_info_OnFail" });
    }
};

/**
 * @method
 * @name dts_nfaith_info_OnLoadError
 * @description dts_nfaith_info 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_nfaith_info_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_nfaith_info);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35101.dts_nfaith_info_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_faith_stat_OnLoadError
 * @description dts_faith_stat 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_faith_stat_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_faith_stat);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35101.dts_faith_stat_OnLoadError" });
    }
};

/**
 * @method
 * @name img_cls_dd_onclick
 * @description img_cls_dd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_cls_dd_onclick = function() {
    try {
        popUpCalendar2(edt_cls_dd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35101.img_cls_dd_onclick" });
    }
};

/**
 * @method
 * @name img_comite_hld_dd_onclick
 * @description img_comite_hld_dd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_comite_hld_dd_onclick = function() {
    try {
        popUpCalendar2(edt_comite_hld_dd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35101.img_comite_hld_dd_onclick" });
    }
};

/**
 * @method
 * @name img_close_onclick
 * @description 「취소」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35101.img_close_onclick" });
    }
};

/**
 * @method
 * @name img_save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_save_onclick = async function() {
    try {
        await scwin.update();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35101.img_save_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    const vClsDd = edt_cls_dd.getValue();
    if (vClsDd > 0 && vClsDd.length < 8) {
        await $c.win.alert("날짜를 올바르게 입력하시오.");
        edt_cls_dd.focus();
        return;
    }
    const vHldDd = edt_comite_hld_dd.getValue();
    if (vHldDd > 0 && vHldDd.length < 8) {
        await $c.win.alert("날짜를 올바르게 입력하시오.");
        edt_comite_hld_dd.focus();
        return;
    }
    const vRemk = txa_remk.getValue();
    if (vRemk.length > 2000) {
        await $c.win.alert("입력한 문자열이 너무 큽니다.");
        txa_remk.focus();
        return;
    }
    dts_nfaith.insertRow();
    dts_nfaith.setCellData(1, "ACPT_NO", scwin.gAcptNo);
    dts_nfaith.setCellData(1, "ISUR_CD", scwin.gIsurCd);
    dts_nfaith.setCellData(1, "EINSPRUCH_CLS_DD", vClsDd);
    dts_nfaith.setCellData(1, "EINSPRUCH_YN", cmb_einspruch_yn.getValue());
    dts_nfaith.setCellData(1, "COMITE_HLD_DD", vHldDd);
    dts_nfaith.setCellData(1, "REMK", vRemk);

    // alert(dts_nfaith.text);

    const vAnswer = confirm('저장 하시겠습니까?');
    if (vAnswer === true) {
        // alert(dts_again.text);
        tr_nfaith_info.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_tr_nfaith_info",
            action : "/UnfaithfulDesignPreview.do",
            ref : "dts_nfaith",
            target : "tr_nfaith_info=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};
